// Included only by this experiment's build.py. Production sources never load it.
const OFFICE_FIDELITY={ready:false,frames:0,textureBytes:0,started:performance.now(),scope:'office1-4; cat-box travel/pop/stop, one ginger turntable, board tiles, cubby faces; native arrival animation'};
