function fidelityTexture(id,rgba,w,h,dx,dy){
  const pixels=new Uint8Array(w*h);for(let i=0;i<pixels.length;i++)pixels[i]=rgba[i*4+3]?C.CREAM:EMPTY;
  return {id,dx,dy,w:w/4,h:h/4,x:AX+dx,y:AY+dy,width:w,height:h,rgba,pixels};
}
function fidelityPrepareLight(){
  const scratch=new Float32Array(WW*WH);fidelityFloorLight=new Float32Array(WW*WH);
  for(let y=0;y<WH;y++)for(let x=0;x<WW;x++){let total=0;for(let d=-3;d<=3;d++)total+=sLvl[y*WW+clamp(x+d,0,WW-1)];scratch[y*WW+x]=total/7;}
  for(let y=0;y<WH;y++)for(let x=0;x<WW;x++){let total=0;for(let d=-3;d<=3;d++)total+=scratch[clamp(y+d,0,WH-1)*WW+x];fidelityFloorLight[y*WW+x]=.88+clamp(total/7-2,0,1)*.16;}
  OFFICE_FIDELITY.textureBytes+=fidelityFloorLight.byteLength;
}
function fidelityResolveSurfaces(){
  if(!OFFICE_FIDELITY.ready||ACTIVE_ROOM.id!=='office'||paperAtlasBuilding)return;
  const S=paperRenderScale(),W=LW*S,H=LH*S,tile=fidelitySurfaces['board-tile'];
  const g=fidelitySurfaces['ginger-cubby'],b=fidelitySurfaces['blue-cubby'];
  for(let py=0;py<H;py++)for(let px=0;px<W;px++){
    const i=py*W+px,c=paperIndex[i]&127;
    const a=(px+.5)/S+viewX-OX,q=(py+.5)/S+viewY-OY;
    let texture=null,u=0,v=0;
    if(c>=C.FT0&&c<=C.FT2){
      const wx=q+a*.5,wy=q-a*.5;
      if(wx>=GX0&&wx<GX1&&wy>=GY0&&wy<GY1){
        texture=tile;u=Math.floor(((wx-GX0)%16)/16*128);v=Math.floor(((wy-GY0)%16)/16*128);
      }
    }else if((c>=C.RD0&&c<=C.RD3)||(c>=C.BL0&&c<=C.BL3)){
      const wx=a+BANK_D,wz=(wx+BANK_D)*.5-q;
      if(wx>=BANK_X0&&wx<BANK_X1&&wz>=BANK_Z0&&wz<BANK_Z1){
        texture=wx<BANK_SPLIT?g:b;u=Math.floor(((wx-BANK_X0)%CUB_W)/CUB_W*128);v=Math.floor(((BANK_Z1-wz)%CUB_H)/CUB_H*144);
      }
    }
    if(!texture)continue;
    // Keep the native static depth and all occlusion. This replaces only a material texel.
    const sx=Math.floor((px+.5)/S+viewX),sy=Math.floor((py+.5)/S+viewY);
    if(sx<0||sy<0||sx>=WW||sy>=WH)continue;
    const source=sy*WW+sx;
    if(fDep[Math.floor(py/S)*LW+Math.floor(px/S)]!==sDep[source]&&paperDepth[i]>sDep[source]+4)continue;
    const k=(v*texture.width+u)*4,alpha=texture.rgba[k+3];
    if(alpha)paperRGBA[i]=fidelityBlend(paperRGBA[i],fidelityPixel(texture,u,v,texture===tile?fidelityFloorLight[source]:1),alpha);
  }
  OFFICE_FIDELITY.frames++;
}
function fidelityDiscTextures(){
  const disc=fidelitySurfaces['ginger-disc'];
  for(let dir=0;dir<4;dir++)for(let pose=0;pose<5;pose++){
    const index=(4+dir)*5+pose,source=paperPieceLookup[0][index];
    const canvas=document.createElement('canvas');canvas.width=source.w*4;canvas.height=source.h*4;
    const c=canvas.getContext('2d');
    // Resize onto the original, pinned piece rectangle. The arrow uses the real direction.
    c.clearRect(0,0,canvas.width,canvas.height);
    c.drawImage(disc.canvas,0,0,canvas.width,canvas.height);
    const points=[[-4,-1.1],[0,-1.1],[0,-3.1],[4.7,0],[0,3.1],[0,1.1],[-4,1.1]];
    const angle=dir*Math.PI/2,cos=Math.cos(angle),sin=Math.sin(angle),cx=-source.dx*4,cy=-source.dy*4;
    c.beginPath();for(let n=0;n<points.length;n++){
      const x=points[n][0]*cos-points[n][1]*sin,y=points[n][0]*sin+points[n][1]*cos;
      const px=cx+(x-y)*4,py=cy+(x+y)*2-2;
      if(n)c.lineTo(px,py);else c.moveTo(px,py);
    }c.closePath();c.fillStyle='#724325';c.fill();
    // Event-controlled registration dots follow the existing turntable clock.
    for(let n=0;n<8;n++){const a=n*Math.PI/4+(pose<4?pose:0)*Math.PI/16;c.beginPath();c.ellipse(cx+Math.cos(a)*26,cy+Math.sin(a)*12,1.4,1,0,0,Math.PI*2);c.fillStyle='#b76c2d';c.fill();}
    const r=fidelityTexture('fidelity-turntable-'+dir+'-'+pose,c.getImageData(0,0,canvas.width,canvas.height).data,canvas.width,canvas.height,source.dx,source.dy);
    paperPieceLookup[0][index]={...source,...r};OFFICE_FIDELITY.textureBytes+=r.rgba.byteLength+r.pixels.byteLength;
  }
}
function fidelityReset(){}

function fidelityStart(){}

