const workshopInk={steel:0x859ca5,edge:0xc2d0ca,frame:0x425b68,dark:0x293f4b,belt:0x58737b,cream:0xe2d4b5,cut:0xb7a47e,brass:0xbb9754,red:0xab4937,timber:0xb98c53};
