function workshopShader(face,u,v){refineState.alpha=255;return refineState.shader?refineState.shader(face,u,v):C.COOL1;}
function workshopFace(face,a,b,c,d,e,colour,shader=null,glass=false){workshopMaterial(colour,glass,shader);paperStaticFace(face,[a,b,c,d,e,workshopShader,C.COOL1,0]);}
function workshopBox(x,y,z,X,Y,Z,colour){workshopFace(F_X,y,Y,z,Z,X,colour);workshopFace(F_Y,x,X,z,Z,Y,colour);workshopFace(F_TOP,x,y,X,Y,Z,colour);}
function workshopQuad(a,b,c,d,colour,face=F_TOP){workshopMaterial(colour);refineState.alpha=255;dpQuad(a,b,c,d,C.COOL1,face);}
function workshopDiskX(x,y,z,r,colour,n=24){workshopMaterial(colour);refineState.alpha=255;for(let k=0;k<n;k++){const a=k/n*TAU,b=(k+1)/n*TAU;dpTri([x,y,z],[x,y+Math.cos(a)*r,z+Math.sin(a)*r],[x,y+Math.cos(b)*r,z+Math.sin(b)*r],C.COOL1,F_X);}}
