function workshopArc(x,mid,z,r0,r1,colour){
 const y0=mid-r1,z0=z;
 workshopFace(F_X,y0,mid+r1,z0,z+r1,x,colour,(face,u,v)=>{const d=Math.hypot(y0+u-mid,v),s=Math.min(d-r0,r1-d);if(s<-.18)return -1;refineState.alpha=Math.round(clamp((s+.18)/.36,0,1)*255);return C.COOL1;});
}
function workshopWindows(){
 const M=workshopInk;
 for(const w of DEPR.windows){const mid=(w.u0+w.u1)/2,r=w.radius;
  // Recessed glass is bounded by a continuous arch, rather than bitmap edge stamps.
  const y0=w.u0+2.5,z0=w.z0+1.5,R=r-2.5;
  workshopFace(F_X,y0,w.u1-2.5,z0,w.springZ+R,-w.depth-.2,0xffffff,(face,u,v)=>{const y=y0+u,z=z0+v,sd=z<=w.springZ?Math.min(y-y0,w.u1-2.5-y,z-z0):Math.min(R-Math.hypot(y-mid,z-w.springZ),z-z0);if(sd<-.18)return -1;refineState.alpha=Math.round(clamp((sd+.18)/.36,0,1)*255);return C.COOL1;},true);
  for(let n=0;n<64;n++){const a=n/64*Math.PI,b=(n+1)/64*Math.PI;workshopQuad([.3,mid+r*Math.cos(a),w.springZ+r*Math.sin(a)],[-w.depth,mid+r*Math.cos(a),w.springZ+r*Math.sin(a)],[-w.depth,mid+r*Math.cos(b),w.springZ+r*Math.sin(b)],[.3,mid+r*Math.cos(b),w.springZ+r*Math.sin(b)],M.cut,F_X);}
  workshopArc(.35,mid,w.springZ,r,r+1.35,M.cream);
  workshopArc(-w.depth+.7,mid,w.springZ,r-2.5,r-1.35,M.frame);
  for(const y of [w.u0+1,w.u1-2.1])workshopBox(-w.depth,y,w.z0+1,-w.depth+1.3,y+1.1,w.springZ+.2,M.frame);
  for(const y of w.mullions)workshopBox(-w.depth+.7,y-.35,w.z0+1.5,-w.depth+1.3,y+.35,w.springZ+r-2.5,M.frame);
  for(const z of w.rails)workshopBox(-w.depth+.7,w.u0+2,z-.35,-w.depth+1.3,w.u1-2,z+.35,M.frame);
  for(const a of [Math.PI/4,Math.PI*3/4])workshopStripX(-w.depth+1.35,mid,w.springZ,mid+(r-2.3)*Math.cos(a),w.springZ+(r-2.3)*Math.sin(a),.38,M.frame);
  // Two folded sill layers and the actual jamb depth give a clean card edge.
  workshopBox(-w.depth-.5,w.u0-1.4,w.z0-2.2,2.1,w.u1+1.4,w.z0-.35,M.cut);
  workshopBox(-w.depth-.7,w.u0-1.7,w.z0-.5,2.5,w.u1+1.7,w.z0-.05,M.cream);
  workshopBox(2.1,w.u0-1.4,w.z0-1.8,2.5,w.u1+1.4,w.z0-.5,0xcdbb98);
 }
}
