  for(const x of [8,22.5])for(const y of incline?[30,45]:[52,96]){const h=H(y)-2;workshopBox(x,y,0,x+1.5,y+1.8,h,M.frame);workshopBox(x-.6,y-.6,0,x+2.1,y+2.4,.6,M.cut);}
  workshopQuad([9.5,y0,H(y0)-1.2],[22.5,y0,H(y0)-1.2],[22.5,y1,H(y1)-1.2],[9.5,y1,H(y1)-1.2],incline?M.belt:M.dark);
  for(const x of [8,23]){workshopQuad([x,y0,H(y0)-3],[x+1.25,y0,H(y0)-3],[x+1.25,y1,H(y1)-3],[x,y1,H(y1)-3],M.frame);workshopQuad([x+1.25,y0,H(y0)-3],[x+1.25,y1,H(y1)-3],[x+1.25,y1,H(y1)+1.1],[x+1.25,y0,H(y0)+1.1],M.frame,F_X);workshopQuad([x,y0,H(y0)+1.1],[x+1.25,y0,H(y0)+1.1],[x+1.25,y1,H(y1)+1.1],[x,y1,H(y1)+1.1],M.edge);}
  for(const x of [9.28,24.28])for(let y=y0+2;y<y1-1;y+=incline?5.6:7.6)workshopDiskX(x,y,H(y)-1,.22,M.brass,8);
  if(incline){for(let y=y0+1+(phase/4)*2.8;y<y1-.6;y+=2.8){const Y=Math.min(y1,y+.48);workshopQuad([10,y,H(y)-.65],[22.5,y,H(y)-.65],[22.5,Y,H(Y)-.65],[10,Y,H(Y)-.65],M.cream);workshopQuad([10,Y,H(Y)-1.2],[22.5,Y,H(Y)-1.2],[22.5,Y,H(Y)-.65],[10,Y,H(Y)-.65],M.cut,F_Y);}for(const x of [9,24])workshopStripX(x,45,3,30,H(30)-3,1,M.steel);}
