 for(const x of [9.4,22])workshopQuad([x,28,H(28)-1.2],[x+.5,28,H(28)-1.2],[x+.5,24,H(24)+.5],[x,24,H(24)+.5],M.frame);
 // The parcel leaves the spiral vertically into the existing dark floor well.
