// Semantic replacements remove the old presentation by source/depth ownership.
// Original logical buffers and Native fine sources are never rewritten.
const refineState={active:false,prepared:false,drawing:false,ink:0,glass:false,shader:null,alpha:255,kind:null,meshes:{},captures:{},depthPool:{},boardRGBPool:{},boardCounts:{},boardBuilding:false,boardGroup:null,builds:0,frames:0,
 coarse:{idx:new Uint8Array(WN).subarray(0,WW*WH),lvl:new Uint8Array(WN).subarray(0,WW*WH),dep:new Int16Array(WN).subarray(0,WW*WH)},day:new Float32Array(WN),blur:new Float32Array(WN),fineDepth:new Int16Array(0),capacity:0,activeDepth:null,activeLength:0,savedSources:new Array(128),
 emission:new Uint32Array(8192),emissionDepth:new Int16Array(8192),emissionCount:0,stats:{vanRecovered:0}};
window.DEPOT_WORKSHOP=refineState;
function refineOn(){return refineState.active&&refineState.prepared&&depotPaperOn();}
const WORKSHOP_STATIC_BACK=['van','bay','windows','yard'],WORKSHOP_STATIC_FRONT=['yard','windows','bay','van'];
function refineBaseDepth(c,coarse,fine){return c&128?coarse:fine;}
function refineCached(s){return !!s.refineSource&&s.idx===s.refineSource.idx;}
function refineScenery(s){return refineCached(s)&&!s.refineSource.refineBoard;}
function refinePacked(v){return ((v>>>16)&255)|(v&0xff00)|((v&255)<<16);}
function refineRGBLight(v,f){let r=Math.min(255,Math.round((v&255)*f)),g=Math.min(255,Math.round((v>>>8&255)*f)),b=Math.min(255,Math.round((v>>>16&255)*f));if(grayscale)r=g=b=Math.round(r*.299+g*.587+b*.114);return (0xff000000|b<<16|g<<8|r)>>>0;}
function refineScreenColour(v,x,y){if(DEPOT_FIDELITY.night)return refineRGBLight(v,.94);const i=Math.floor(y)*WW+Math.floor(x),f=x>=0&&x<WW&&y>=0&&y<WH?refineState.day[i]:.94;return refineRGBLight(v,f);}
