 if(o.service){let i=0,travel=0;while(i<INTER_PATH.length-2&&f>=INTER_PATH[i+1][0]){const a=INTER_PATH[i],b=INTER_PATH[i+1];travel+=Math.hypot(b[1]-a[1],b[2]-a[2]);i++;}const a=INTER_PATH[i],b=INTER_PATH[i+1],t=(f-a[0])/(b[0]-a[0]),dx=b[1]-a[1],dy=b[2]-a[2];o.x=a[1]+dx*t;o.y=a[2]+dy*t;travel+=Math.hypot(dx,dy)*t;if(dx||dy){o.face=Math.abs(dx)>Math.abs(dy)?dx>0?1:2:dy>0?0:3;o.walk=Math.floor(travel/8*4)&3;}else{o.face=2;o.walk=-1;}}
