function depotPrepareFields(){
 const d=depotLight,P=FIDELITY_DEPOT_PROFILE.light,B=gm.L.board,bx=(gBoardX(B)+B.w/2)*16,by=(gBoardY(B)+B.h/2)*16,cx=OX+bx-by,cy=OY+(bx+by)/2-5;
 d.day.fill(.88);d.scratch.fill(0);d.night.fill(P.background);
 for(let y=0;y<WH;y++)for(let x=0;x<WW;x++){let total=0;for(let k=-3;k<=3;k++)total+=sLvl[y*WW+clamp(x+k,0,WW-1)];d.scratch[y*WW+x]=total/7;}
 for(let y=0;y<WH;y++)for(let x=0;x<WW;x++){
  let total=0;for(let k=-3;k<=3;k++)total+=d.scratch[clamp(y+k,0,WH-1)*WW+x];d.day[y*WW+x]=.88+clamp(total/7-2,0,1)*.16;
  const a=(x-cx)/((B.w+B.h)*8),b=(y-cy)/((B.w+B.h)*4),board=Math.exp(-a*a-b*b);let warm=0;
  for(const l of DEPR.lamps){if(!l.on)continue;const u=(x-(OX+l.x-l.y))/(l.pool*1.2),v=(y-(OY+(l.x+l.y)*.5))/(l.pool*.65);warm=Math.max(warm,Math.exp(-u*u-v*v));}
  const r=Math.round(128*(P.ambient[0]+P.board[0]*board+P.lamp[0]*warm)),g=Math.round(128*(P.ambient[1]+P.board[1]*board+P.lamp[1]*warm)),bl=Math.round(128*(P.ambient[2]+P.board[2]*board+P.lamp[2]*warm));d.night[y*WW+x]=(bl<<16)|(g<<8)|r;
 }
 d.builds++;DEPOT_FIDELITY.generation++;
}
